<template>
  <section class="bridge-edit-page">
    <div class="edit-heading"><div><span>桥梁档案</span><h2>{{ editing ? '编辑桥梁基础状况' : '新增桥梁基础状况' }}</h2></div><div><el-button @click="router.back()">取消</el-button><el-button type="primary" :loading="saving" @click="save"><Save :size="16"/>保存档案</el-button></div></div>
    <el-form label-position="top">
      <EditSection code="A" title="桥梁所处行政区划" subtitle="位置和坐标信息"><div class="form-grid"><Field v-for="item in areaFields" :key="item.key" :item="item"/></div></EditSection>
      <EditSection code="B" title="行政识别数据" subtitle="路线、桥梁身份及建设单位"><div class="form-grid"><el-form-item label="桥梁编号" required><el-input v-model="form.bridge_code" :disabled="editing"/></el-form-item><el-form-item label="桥梁名称" required><el-input v-model="form.bridge_name"/></el-form-item><el-form-item label="路线"><el-select v-model="form.route_code" filterable style="width:100%"><el-option v-for="item in routes" :key="item.route_code" :label="`${item.route_code} · ${item.route_name}`" :value="item.route_code"/></el-select></el-form-item><el-form-item label="桥梁类型"><el-select v-model="form.bridge_type_code" filterable style="width:100%"><el-option v-for="item in bridgeTypes" :key="item.bridge_type_code" :label="item.bridge_type_name" :value="item.bridge_type_code"/></el-select></el-form-item><Field v-for="item in identityFields" :key="item.key" :item="item"/></div></EditSection>
      <EditSection code="C" title="桥梁技术指标" subtitle="桥面、净空、引道和水文指标"><div class="form-grid"><Field v-for="item in technicalFields" :key="item.key" :item="item"/></div></EditSection>
      <EditSection code="D" title="桥梁结构信息" subtitle="设置数量后生成与表 A 对应的动态列">
        <section class="dimension-panel"><div><b>结构维度配置</b><span>先设置测点、孔号、索号和墩台数量，系统按数量生成可填写的正式表格列。</span></div><div class="dimension-grid"><el-form-item v-for="item in dimensionFields" :key="item.key" :label="item.label"><el-input-number v-model="repeatCounts[item.key]" :min="0" :max="99" controls-position="right" style="width:100%"/></el-form-item></div><div class="dimension-actions"><el-button type="primary" @click="applyCounts">按数量生成/调整明细</el-button><small>减少数量会删除末尾明细，保存前会提示确认。</small></div></section>
        <DetailTitle title="桥面高程测点（A表34）" button="增加测点" @add="addMeasurementPoint"/><el-table :data="structures.measurementPoints" border><el-table-column label="测点编号" width="130"><template #default="{row}"><el-input v-model="row.point_no"/></template></el-table-column><el-table-column label="测点名称"><template #default="{row}"><el-input v-model="row.point_name"/></template></el-table-column><el-table-column label="基准高程（m）"><template #default="{row}"><el-input v-model="row.benchmark_elevation"/></template></el-table-column><el-table-column label="说明"><template #default="{row}"><el-input v-model="row.remark"/></template></el-table-column><RemoveColumn @remove="index=>structures.measurementPoints.splice(index,1)"/></el-table>
        <DetailTitle title="桥梁分孔（A表35）" button="增加一孔" @add="addSpan"/><el-table :data="structures.spans" border><el-table-column label="孔号" width="100"><template #default="{row}"><el-input-number v-model="row.span_no" :min="1" controls-position="right"/></template></el-table-column><el-table-column label="跨径（m）"><template #default="{row}"><el-input v-model="row.span_length"/></template></el-table-column><el-table-column label="结构形式"><template #default="{row}"><el-input v-model="row.structure_form"/></template></el-table-column><el-table-column label="材料"><template #default="{row}"><el-input v-model="row.material_type"/></template></el-table-column><RemoveColumn @remove="index=>structures.spans.splice(index,1)"/></el-table>
        <DetailTitle title="五类结构形式与材料" button="增加结构明细" @add="addStructure"/><el-table :data="structures.structures" border><el-table-column label="分类" width="190"><template #default="{row}"><el-select v-model="row.structure_group"><el-option v-for="item in structureGroups" :key="item.value" :label="item.label" :value="item.value"/></el-select></template></el-table-column><el-table-column label="结构类型" width="160"><template #default="{row}"><el-input v-model="row.structure_type"/></template></el-table-column><el-table-column label="编号" width="120"><template #default="{row}"><el-input v-model="row.serial_no"/></template></el-table-column><el-table-column label="形式"><template #default="{row}"><el-input v-model="row.form"/></template></el-table-column><el-table-column label="材料"><template #default="{row}"><el-input v-model="row.material_type"/></template></el-table-column><el-table-column label="数量" width="100"><template #default="{row}"><el-input v-model="row.quantity"/></template></el-table-column><RemoveColumn @remove="index=>structures.structures.splice(index,1)"/></el-table>
        <DetailTitle title="斜拉索、吊杆、系杆（含索力）" button="增加索" @add="addCable"/><el-table :data="structures.cables" border><el-table-column label="索类型" width="140"><template #default="{row}"><el-select v-model="row.cable_type"><el-option v-for="item in cableTypes" :key="item" :label="item" :value="item"/></el-select></template></el-table-column><el-table-column label="编号" width="120"><template #default="{row}"><el-input v-model="row.serial_no"/></template></el-table-column><el-table-column label="索力"><template #default="{row}"><el-input v-model="row.force_value"/></template></el-table-column><el-table-column label="材料"><template #default="{row}"><el-input v-model="row.material_type"/></template></el-table-column><el-table-column label="位置"><template #default="{row}"><el-input v-model="row.location_desc"/></template></el-table-column><RemoveColumn @remove="index=>structures.cables.splice(index,1)"/></el-table>
      </EditSection>
      <EditSection code="H" title="需要说明的事项" subtitle="管养单位变更或待核验信息"><div class="form-grid"><Field v-for="item in extraFields" :key="item.key" :item="item"/><el-form-item label="需要说明的事项" class="full-row"><el-input v-model="form.notes" type="textarea" :rows="4"/></el-form-item></div></EditSection>
    </el-form>
  </section>
</template>

<script setup>
import { defineComponent, h, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElButton, ElFormItem, ElInput, ElMessage, ElMessageBox, ElTableColumn } from 'element-plus'
import { Plus, Save } from 'lucide-vue-next'
import http from '../api/http'

const route=useRoute(),router=useRouter(),editing=ref(Boolean(route.params.bridgeCode)),saving=ref(false),routes=ref([]),bridgeTypes=ref([]),form=reactive({}),structures=reactive({spans:[],structures:[],cables:[],measurementPoints:[]})
const repeatCounts=reactive({deckElevationPoints:0,spans:0,structuralSystems:0,stayCables:0,hangers:0,tieRods:0,expansionJoints:0,railingPositions:0,abutments:0,piers:0,anchors:0,bearings:0})
const make=items=>items.map(([key,label])=>({key,label}))
const areaFields=make([['administrative_code','行政区划代码'],['location_address','桥梁详细地址'],['longitude','经度'],['latitude','纬度']])
const identityFields=make([['pile_number','桥位桩号'],['function_type','功能类型'],['maintenance_level','养护检查等级'],['built_year','建成年份'],['completion_date','竣工时间'],['design_load','设计荷载'],['design_unit','设计单位'],['construction_unit','施工单位'],['supervision_unit','监理单位'],['owner_unit','业主单位'],['management_unit','管养单位'],['road_management_org','公路管理机构']])
const technicalFields=make([['bridge_length','桥梁全长（m）'],['deck_width','桥面总宽（m）'],['lane_width','车道宽度（m）'],['sidewalk_width','人行道宽度（m）'],['barrier_height','护栏或防撞墙高度（m）'],['median_width','中央分隔带宽度（m）'],['standard_clearance','桥面标准净空'],['actual_clearance','桥面实际净空'],['navigation_standard','桥下通航等级及标准净空'],['navigation_actual','桥下实际净空'],['approach_width','引道总宽（m）'],['approach_alignment','引道线形或曲线半径'],['design_flood','设计洪水频率及水位'],['historical_flood','历史洪水位'],['seismic_coefficient','地震动峰值加速度系数']])
const extraFields=make([['structural_system','结构体系'],['span_combination','桥梁分联及跨径组合'],['bridge_engineer','桥梁工程师'],['card_filler','填卡人'],['card_date','填卡日期']])
const structureGroups=[{value:'superstructure',label:'上部结构形式与材料'},{value:'deck',label:'桥面系形式与材料'},{value:'substructure',label:'下部结构形式与材料'},{value:'foundation',label:'基础形式与材料'},{value:'bearing_facility',label:'支座形式、材料与附属设施'}]
const cableTypes=['斜拉索','吊杆','系杆']
const dimensionFields=[['deckElevationPoints','桥面高程测点数'],['spans','桥梁分孔数'],['structuralSystems','结构体系种类数'],['stayCables','斜拉索数'],['hangers','吊杆数'],['tieRods','系杆数'],['expansionJoints','伸缩缝数'],['railingPositions','栏杆/护栏部位数'],['abutments','桥台数'],['piers','桥墩数'],['anchors','锚碇数'],['bearings','支座数']].map(([key,label])=>({key,label}))
const EditSection=defineComponent({props:{code:String,title:String,subtitle:String},setup:(p,{slots})=>()=>h('section',{class:'edit-section'},[h('div',{class:'section-head'},[h('b',p.code),h('div',[h('h3',p.title),h('span',p.subtitle)])]),slots.default?.()])})
const Field=defineComponent({props:{item:Object},setup:p=>()=>h(ElFormItem,{label:p.item.label},()=>h(ElInput,{modelValue:form[p.item.key],onInput:value=>form[p.item.key]=value}))})
const DetailTitle=defineComponent({emits:['add'],props:{title:String,button:String},setup:(p,{emit})=>()=>h('div',{class:'detail-toolbar'},[h('strong',p.title),h(ElButton,{size:'small',onClick:()=>emit('add')},()=>[h(Plus,{size:14}),p.button])])})
const RemoveColumn=defineComponent({emits:['remove'],setup:(_,{emit})=>()=>h(ElTableColumn,{label:'操作',width:80},{default:scope=>h(ElButton,{text:true,type:'danger',onClick:()=>emit('remove',scope.$index)},()=> '删除')})})

function addMeasurementPoint(){structures.measurementPoints.push({point_category:'deck_elevation',point_no:`测点${structures.measurementPoints.length+1}`,point_name:'',benchmark_elevation:'',remark:''})}
function addSpan(){structures.spans.push({span_no:structures.spans.length+1,span_length:'',structure_form:'',material_type:''})}
function addStructure(){structures.structures.push({structure_group:'superstructure',structure_type:'',serial_no:String(structures.structures.length+1),form:'',material_type:'',quantity:1})}
function addCable(){structures.cables.push({cable_type:'斜拉索',serial_no:String(structures.cables.length+1),force_value:'',material_type:'',location_desc:''})}
function structureRows(group,type){return structures.structures.filter(row=>row.structure_group===group&&row.structure_type===type)}
function cableRows(type){return structures.cables.filter(row=>row.cable_type===type)}
function setRows(target,predicate,count,factory){const current=target.filter(predicate),targetCount=Math.max(0,Number(count)||0);for(let index=target.length-1;current.length>targetCount&&index>=0;index--){if(predicate(target[index])){target.splice(index,1);current.pop()}}for(let index=current.length;index<targetCount;index++)target.push(factory(index+1))}
async function applyCounts(){const reductions=[['测点',structures.measurementPoints.length,repeatCounts.deckElevationPoints],['分孔',structures.spans.length,repeatCounts.spans],['斜拉索',cableRows('斜拉索').length,repeatCounts.stayCables],['吊杆',cableRows('吊杆').length,repeatCounts.hangers],['系杆',cableRows('系杆').length,repeatCounts.tieRods],['桥台',structureRows('substructure','桥台').length,repeatCounts.abutments],['桥墩',structureRows('substructure','桥墩').length,repeatCounts.piers],['锚碇',structureRows('foundation','锚碇').length,repeatCounts.anchors],['支座',structureRows('bearing_facility','支座').length,repeatCounts.bearings]].filter(([,current,next])=>Number(next)<current);if(reductions.length)await ElMessageBox.confirm(`将删除末尾的${reductions.map(([name,current,next])=>`${name}${current-next}条`).join('、')}，保存后不可恢复。`, '确认调整结构数量', {type:'warning',confirmButtonText:'继续调整',cancelButtonText:'取消'});setRows(structures.measurementPoints,()=>true,repeatCounts.deckElevationPoints,index=>({point_category:'deck_elevation',point_no:`测点${index}`,point_name:'',benchmark_elevation:'',remark:''}));setRows(structures.spans,()=>true,repeatCounts.spans,index=>({span_no:index,span_length:'',structure_form:'',material_type:''}));setRows(structures.structures,row=>row.structure_group==='superstructure'&&row.structure_type==='结构体系',repeatCounts.structuralSystems,index=>({structure_group:'superstructure',structure_type:'结构体系',serial_no:`体系${index}`,form:'',material_type:'',quantity:1}));setRows(structures.cables,row=>row.cable_type==='斜拉索',repeatCounts.stayCables,index=>({cable_type:'斜拉索',serial_no:`${index}号索`,force_value:'',material_type:'',location_desc:''}));setRows(structures.cables,row=>row.cable_type==='吊杆',repeatCounts.hangers,index=>({cable_type:'吊杆',serial_no:`${index}号吊杆`,force_value:'',material_type:'',location_desc:''}));setRows(structures.cables,row=>row.cable_type==='系杆',repeatCounts.tieRods,index=>({cable_type:'系杆',serial_no:`${index}号系杆`,force_value:'',material_type:'',location_desc:''}));setRows(structures.structures,row=>row.structure_group==='deck'&&row.structure_type==='伸缩缝',repeatCounts.expansionJoints,index=>({structure_group:'deck',structure_type:'伸缩缝',serial_no:`${index}号`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='deck'&&row.structure_type==='栏杆、护栏',repeatCounts.railingPositions,index=>({structure_group:'deck',structure_type:'栏杆、护栏',serial_no:`部位${index}`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='substructure'&&row.structure_type==='桥台',repeatCounts.abutments,index=>({structure_group:'substructure',structure_type:'桥台',serial_no:`${index}号台`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='substructure'&&row.structure_type==='桥墩',repeatCounts.piers,index=>({structure_group:'substructure',structure_type:'桥墩',serial_no:`${index}号墩`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='foundation'&&row.structure_type==='锚碇',repeatCounts.anchors,index=>({structure_group:'foundation',structure_type:'锚碇',serial_no:`${index}号锚碇`,form:'',material_type:'',quantity:1}));setRows(structures.structures,row=>row.structure_group==='bearing_facility'&&row.structure_type==='支座',repeatCounts.bearings,index=>({structure_group:'bearing_facility',structure_type:'支座',serial_no:`${index}号`,form:'',material_type:'',quantity:1}));ElMessage.success('结构明细已按数量生成')}
function syncRepeatCounts(){repeatCounts.deckElevationPoints=structures.measurementPoints?.length||0;repeatCounts.spans=structures.spans.length;repeatCounts.structuralSystems=structureRows('superstructure','结构体系').length;repeatCounts.stayCables=cableRows('斜拉索').length;repeatCounts.hangers=cableRows('吊杆').length;repeatCounts.tieRods=cableRows('系杆').length;repeatCounts.expansionJoints=structureRows('deck','伸缩缝').length;repeatCounts.railingPositions=structureRows('deck','栏杆、护栏').length;repeatCounts.abutments=structureRows('substructure','桥台').length;repeatCounts.piers=structureRows('substructure','桥墩').length;repeatCounts.anchors=structureRows('foundation','锚碇').length;repeatCounts.bearings=structureRows('bearing_facility','支座').length}
async function load(){const [routeData,typeData]=await Promise.all([http.get('/routes',{params:{size:100}}),http.get('/bridge-types',{params:{size:100}})]);routes.value=routeData.records;bridgeTypes.value=typeData.records;if(editing.value){Object.assign(form,await http.get(`/bridges/${route.params.bridgeCode}`));Object.assign(structures,await http.get(`/bridge-profiles/${route.params.bridgeCode}/structures`));syncRepeatCounts()}}
async function save(){if(!form.bridge_code||!form.bridge_name||!form.route_code||!form.bridge_type_code){ElMessage.warning('请填写桥梁编号、名称、路线和桥梁类型');return}saving.value=true;try{let code=form.bridge_code;if(editing.value)await http.put(`/bridges/${route.params.bridgeCode}`,form);else code=(await http.post('/bridges',form)).bridge_code;await http.put(`/bridge-profiles/${code}/structures`,structures);ElMessage.success('桥梁档案保存成功');router.push(`/bridges/${code}/A`)}finally{saving.value=false}}
onMounted(load)
</script>

<style scoped>
.bridge-edit-page{max-width:1500px;margin:auto}.edit-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.edit-heading span{color:#0f766e;font-size:12px;font-weight:700}.edit-heading h2{margin:5px 0 0}.edit-heading>div:last-child{display:flex;gap:8px}.edit-heading .el-button{display:flex;gap:6px}.edit-section{background:#fff;border:1px solid #dbe3ec;border-radius:8px;margin-bottom:14px;overflow:hidden}.section-head{display:flex;align-items:center;gap:12px;padding:14px 18px;background:#f8fafc;border-bottom:1px solid #dbe3ec}.section-head>b{display:grid;place-items:center;width:34px;height:34px;background:#0f766e;color:#fff;border-radius:6px}.section-head h3{margin:0;font-size:16px}.section-head span{color:#64748b;font-size:11px}.form-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px 16px;padding:18px}.full-row{grid-column:1/-1}.detail-toolbar{display:flex;align-items:center;justify-content:space-between;padding:14px 18px 10px}.detail-toolbar .el-button{display:flex;gap:4px}.dimension-panel{margin:16px;border:1px solid #b7ded9;border-radius:10px;background:#f0fdfa;padding:16px}.dimension-panel b,.dimension-panel span{display:block}.dimension-panel b{color:#115e59}.dimension-panel span{font-size:12px;color:#45635f;margin-top:4px}.dimension-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px 14px;margin-top:12px}.dimension-actions{display:flex;align-items:center;gap:12px;margin-top:4px}.dimension-actions small{color:#64748b}@media(max-width:1050px){.form-grid,.dimension-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:680px){.form-grid,.dimension-grid{grid-template-columns:1fr}.full-row{grid-column:auto}.edit-heading,.dimension-actions{align-items:flex-start;flex-direction:column;gap:12px}}
</style>
